from taf.internal.cloud.lcmaas.client.lcmaas.v1 import CnfPackageApi, CnfPackageIn


class CnfPackageV1(object):
    def __init__(self, api_client):
        self.cnf_pkg_api = CnfPackageApi(api_client=api_client)

    def create_cnf_package(self, cnf_pkg_name, cnf_pkg_url):
        cnf_pkg_data = CnfPackageIn(name=cnf_pkg_name, url=cnf_pkg_url)
        return self.cnf_pkg_api.create_cnf_pkg(cnf_package_in=cnf_pkg_data)

    def get_cnf_package_info_by_name(self, cnf_pkg_name):
        return self.cnf_pkg_api.get_cnf_pkg_by_name(cnf_pkg_name=cnf_pkg_name)

    def get_cnf_packages_info(self):
        return self.cnf_pkg_api.get_cnf_pkgs()

    def delete_cnf_pkg(self, cnf_pkg_name):
        return self.cnf_pkg_api.delete_cnf_pkg_by_name(cnf_pkg_name=cnf_pkg_name)
